import{_ as t,o as s,c as a,a0 as d}from"./chunks/framework.BDx3ik-m.js";const m=JSON.parse('{"title":"EPIC 39: Tariffs Type & Parameter Fixes — CommissionUzbekistan fields, missing types, date param signatures","description":"","frontmatter":{},"headers":[],"relativePath":"epics/EPIC_39_TARIFFS_TYPE_PARAMETER_FIXES.md","filePath":"epics/EPIC_39_TARIFFS_TYPE_PARAMETER_FIXES.md"}'),i={name:"epics/EPIC_39_TARIFFS_TYPE_PARAMETER_FIXES.md"};function o(r,e,n,c,l,p){return s(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="epic-39-tariffs-type-parameter-fixes-—-commissionuzbekistan-fields-missing-types-date-param-signatures" tabindex="-1">EPIC 39: Tariffs Type &amp; Parameter Fixes — CommissionUzbekistan fields, missing types, date param signatures <a class="header-anchor" href="#epic-39-tariffs-type-parameter-fixes-—-commissionuzbekistan-fields-missing-types-date-param-signatures" aria-label="Permalink to &quot;EPIC 39: Tariffs Type &amp; Parameter Fixes — CommissionUzbekistan fields, missing types, date param signatures&quot;">​</a></h1><h2 id="status-✅-complete" tabindex="-1">Status: ✅ COMPLETE <a class="header-anchor" href="#status-✅-complete" aria-label="Permalink to &quot;Status: ✅ COMPLETE&quot;">​</a></h2><p><strong>Completed</strong>: 2026-02-06 <strong>Backlog Task</strong>: task-39 (Done)</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Epic</strong></td><td>39</td></tr><tr><td><strong>Module</strong></td><td>tariffs (<code>10-tariffs.yaml</code>)</td></tr><tr><td><strong>Priority</strong></td><td>High</td></tr><tr><td><strong>Target SDK Version</strong></td><td>v2.7.x</td></tr><tr><td><strong>Backlog Task</strong></td><td>task-39</td></tr><tr><td><strong>Depends On</strong></td><td>None</td></tr><tr><td><strong>Source</strong></td><td>February 2026 Swagger Audit</td></tr><tr><td><strong>Related Stories</strong></td><td>4.5 (Promotion &amp; Tariffs Modules), 7.7 (Tariffs Validation Issues)</td></tr></tbody></table><hr><h2 id="current-state" tabindex="-1">Current State <a class="header-anchor" href="#current-state" aria-label="Permalink to &quot;Current State&quot;">​</a></h2><h3 id="what-exists" tabindex="-1">What Exists <a class="header-anchor" href="#what-exists" aria-label="Permalink to &quot;What Exists&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Asset</th><th>Path</th><th>Details</th></tr></thead><tbody><tr><td>Module implementation</td><td><code>src/modules/tariffs/index.ts</code></td><td>89 lines, 4 methods</td></tr><tr><td>Types file</td><td><code>src/types/tariffs.types.ts</code></td><td>227 lines, 18 interfaces</td></tr><tr><td>Rate limits</td><td><code>src/config/tariffs-rate-limits.ts</code></td><td>4 entries</td></tr><tr><td>Unit tests</td><td><code>tests/unit/modules/tariffs.test.ts</code></td><td>668 lines, 29 tests, 6 skipped</td></tr><tr><td>Swagger spec</td><td><code>wildberries_api_doc/10-tariffs.yaml</code></td><td>5 endpoints, 20 schemas</td></tr><tr><td>Swagger shards</td><td><code>wildberries_api_doc/10-tariffs/</code></td><td>4 shards</td></tr></tbody></table><h3 id="what-is-wrong" tabindex="-1">What Is Wrong <a class="header-anchor" href="#what-is-wrong" aria-label="Permalink to &quot;What Is Wrong&quot;">​</a></h3><p>Three critical issues have been identified in the tariffs module:</p><ol><li><p><strong>CommissionUzbekistan type mismatch (CRITICAL)</strong>: The SDK defines a single <code>kgvpUzbekistan</code> field in the <code>CommissionUzbekistan</code> interface. The swagger specification defines 3 separate fields: <code>kgvpMarketplaceUz</code> (FBS commission), <code>kgvpPaidStorageUz</code> (FBW commission), and <code>kgvpSupplierUz</code> (DBS commission). This is a data integrity bug — Uzbekistan commissions cannot be correctly represented.</p></li><li><p><strong>2 missing types (MEDIUM)</strong>: <code>models.ErrorModel</code> (used in 400 responses) and <code>models.AcceptanceCoefficient</code> (used by the acceptance coefficients endpoint) are not present in <code>tariffs.types.ts</code>. <code>AcceptanceCoefficient</code> exists in <code>orders-fbw.types.ts</code> but also belongs in the tariffs types.</p></li><li><p><strong>Required date parameter bug (HIGH)</strong>: 3 methods (<code>getTariffsBox</code>, <code>getTariffsPallet</code>, <code>getTariffsReturn</code>) wrap the <code>date</code> parameter inside an <code>options?</code> optional object, but the swagger requires <code>date</code> as mandatory. This causes HTTP 400 errors, as documented in story 7.7 and confirmed by 6 skipped unit tests.</p></li></ol><h3 id="why-this-matters" tabindex="-1">Why This Matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why This Matters&quot;">​</a></h3><ul><li><strong>Uzbekistan commissions are silently wrong</strong>: Any code using <code>kgvpUzbekistan</code> gets incomplete data — FBS, FBW, and DBS commissions are collapsed into a single field that does not exist in the API response</li><li><strong>Missing error type</strong>: Without <code>models.ErrorModel</code>, 400 responses cannot be properly typed or handled</li><li><strong>Methods fail at runtime</strong>: The 3 box/pallet/return tariff methods will always return HTTP 400 when called without a date, yet the SDK signature allows omitting it</li><li><strong>6 skipped tests</strong>: Test coverage is incomplete, masking real bugs</li></ul><hr><h2 id="gap-analysis" tabindex="-1">Gap Analysis <a class="header-anchor" href="#gap-analysis" aria-label="Permalink to &quot;Gap Analysis&quot;">​</a></h2><h3 id="commissionuzbekistan-field-comparison" tabindex="-1">CommissionUzbekistan Field Comparison <a class="header-anchor" href="#commissionuzbekistan-field-comparison" aria-label="Permalink to &quot;CommissionUzbekistan Field Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>SDK Field</th><th>Swagger Fields</th><th>Meaning</th></tr></thead><tbody><tr><td><code>kgvpUzbekistan</code> (single field)</td><td><code>kgvpMarketplaceUz</code></td><td>FBS commission (marketplace fulfillment)</td></tr><tr><td></td><td><code>kgvpPaidStorageUz</code></td><td>FBW commission (paid storage fulfillment)</td></tr><tr><td></td><td><code>kgvpSupplierUz</code></td><td>DBS commission (supplier fulfillment)</td></tr></tbody></table><h3 id="missing-types" tabindex="-1">Missing Types <a class="header-anchor" href="#missing-types" aria-label="Permalink to &quot;Missing Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Schema Name</th><th>Purpose</th><th>Used By</th></tr></thead><tbody><tr><td><code>models.ErrorModel</code></td><td>Standard error response for 400 status codes</td><td>All tariff endpoints</td></tr><tr><td><code>models.AcceptanceCoefficient</code></td><td>Acceptance coefficient data</td><td>Acceptance coefficients endpoint</td></tr></tbody></table><h3 id="method-signature-issues" tabindex="-1">Method Signature Issues <a class="header-anchor" href="#method-signature-issues" aria-label="Permalink to &quot;Method Signature Issues&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Current Signature</th><th>Required Signature</th><th>Impact</th></tr></thead><tbody><tr><td><code>getTariffsBox</code></td><td><code>options?: { date?: string }</code></td><td><code>date: string</code> (required)</td><td>HTTP 400 without date</td></tr><tr><td><code>getTariffsPallet</code></td><td><code>options?: { date?: string }</code></td><td><code>date: string</code> (required)</td><td>HTTP 400 without date</td></tr><tr><td><code>getTariffsReturn</code></td><td><code>options?: { date?: string }</code></td><td><code>date: string</code> (required)</td><td>HTTP 400 without date</td></tr></tbody></table><hr><h2 id="implementation-approach" tabindex="-1">Implementation Approach <a class="header-anchor" href="#implementation-approach" aria-label="Permalink to &quot;Implementation Approach&quot;">​</a></h2><h3 id="step-1-fix-commissionuzbekistan-interface" tabindex="-1">Step 1: Fix CommissionUzbekistan Interface <a class="header-anchor" href="#step-1-fix-commissionuzbekistan-interface" aria-label="Permalink to &quot;Step 1: Fix CommissionUzbekistan Interface&quot;">​</a></h3><p>Replace the single <code>kgvpUzbekistan</code> field with the 3 correct fields from the swagger: <code>kgvpMarketplaceUz</code>, <code>kgvpPaidStorageUz</code>, <code>kgvpSupplierUz</code>.</p><h3 id="step-2-add-models-errormodel-type" tabindex="-1">Step 2: Add models.ErrorModel Type <a class="header-anchor" href="#step-2-add-models-errormodel-type" aria-label="Permalink to &quot;Step 2: Add models.ErrorModel Type&quot;">​</a></h3><p>Add the <code>ErrorModel</code> interface to <code>tariffs.types.ts</code> based on the swagger schema for 400 responses.</p><h3 id="step-3-add-models-acceptancecoefficient-type" tabindex="-1">Step 3: Add models.AcceptanceCoefficient Type <a class="header-anchor" href="#step-3-add-models-acceptancecoefficient-type" aria-label="Permalink to &quot;Step 3: Add models.AcceptanceCoefficient Type&quot;">​</a></h3><p>Add the <code>AcceptanceCoefficient</code> interface to <code>tariffs.types.ts</code> based on the swagger schema for the acceptance coefficients endpoint.</p><h3 id="step-4-fix-method-signatures" tabindex="-1">Step 4: Fix Method Signatures <a class="header-anchor" href="#step-4-fix-method-signatures" aria-label="Permalink to &quot;Step 4: Fix Method Signatures&quot;">​</a></h3><p>Update <code>getTariffsBox</code>, <code>getTariffsPallet</code>, and <code>getTariffsReturn</code> to make the <code>date</code> parameter required instead of wrapped in an optional object.</p><h3 id="step-5-un-skip-and-fix-unit-tests" tabindex="-1">Step 5: Un-skip and Fix Unit Tests <a class="header-anchor" href="#step-5-un-skip-and-fix-unit-tests" aria-label="Permalink to &quot;Step 5: Un-skip and Fix Unit Tests&quot;">​</a></h3><p>Un-skip the 6 date validation unit tests and update them to match the corrected method signatures.</p><h3 id="step-6-validate-type-safety" tabindex="-1">Step 6: Validate Type Safety <a class="header-anchor" href="#step-6-validate-type-safety" aria-label="Permalink to &quot;Step 6: Validate Type Safety&quot;">​</a></h3><p>Run <code>npx tsc --noEmit</code> to ensure zero type errors across the project and verify no regressions.</p><hr><h2 id="files-to-modify" tabindex="-1">Files to Modify <a class="header-anchor" href="#files-to-modify" aria-label="Permalink to &quot;Files to Modify&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Changes</th><th>Estimated Effort</th></tr></thead><tbody><tr><td><code>src/types/tariffs.types.ts</code></td><td>Fix CommissionUzbekistan fields, add 2 new types</td><td>Medium</td></tr><tr><td><code>src/modules/tariffs/index.ts</code></td><td>Fix 3 method signatures (date required)</td><td>Low</td></tr><tr><td><code>tests/unit/modules/tariffs.test.ts</code></td><td>Un-skip 6 tests, update for new signatures</td><td>Low</td></tr></tbody></table><hr><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>[x] CommissionUzbekistan has 3 correct fields per swagger (<code>kgvpMarketplaceUz</code>, <code>kgvpPaidStorageUz</code>, <code>kgvpSupplierUz</code>)</li><li>[x] <code>models.ErrorModel</code> type added to <code>tariffs.types.ts</code></li><li>[x] <code>models.AcceptanceCoefficient</code> type added to <code>tariffs.types.ts</code></li><li>[x] 3 method signatures require <code>date</code> parameter</li><li>[x] 6 previously skipped tests now pass</li><li>[x] TypeScript strict mode passes (<code>npx tsc --noEmit</code> exits 0)</li><li>[x] No regressions in existing code importing tariffs types</li></ul><hr><h2 id="risk-assessment" tabindex="-1">Risk Assessment <a class="header-anchor" href="#risk-assessment" aria-label="Permalink to &quot;Risk Assessment&quot;">​</a></h2><p><strong>Risk Level: MEDIUM</strong></p><ul><li><strong>CommissionUzbekistan field rename is a BREAKING CHANGE</strong>: Any code using <code>kgvpUzbekistan</code> will fail to compile. This is intentional — the old field was incorrect and did not match the API response.</li><li><strong>Date parameter signature change is technically breaking</strong>: However, this fixes a bug — methods did not work without the date parameter, so any working consumer code was already providing it.</li><li><strong>Adding new types is non-breaking</strong>: <code>ErrorModel</code> and <code>AcceptanceCoefficient</code> are additive changes.</li></ul><hr><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Path</th></tr></thead><tbody><tr><td>Swagger spec</td><td><code>wildberries_api_doc/10-tariffs.yaml</code></td></tr><tr><td>Swagger shards</td><td><code>wildberries_api_doc/10-tariffs/</code> (4 shards)</td></tr><tr><td>Module source</td><td><code>src/modules/tariffs/index.ts</code> (89 lines)</td></tr><tr><td>Types file</td><td><code>src/types/tariffs.types.ts</code> (227 lines)</td></tr><tr><td>Unit tests</td><td><code>tests/unit/modules/tariffs.test.ts</code> (668 lines)</td></tr><tr><td>Story 4.5</td><td><code>docs/stories/4.5.promotion-tariffs-modules.md</code></td></tr><tr><td>Story 7.7</td><td><code>docs/stories/7.7.tariffs-validation-issues.md</code></td></tr><tr><td>QA Gate 4.5</td><td><code>docs/qa/gates/4.5-promotion-tariffs-modules.yml</code></td></tr><tr><td>EPIC 40 (code quality)</td><td><code>docs/epics/EPIC_40_TARIFFS_CODE_QUALITY.md</code></td></tr><tr><td>Backlog task</td><td><code>backlog/tasks/task-39</code></td></tr></tbody></table><hr><h2 id="implementation-notes" tabindex="-1">Implementation Notes <a class="header-anchor" href="#implementation-notes" aria-label="Permalink to &quot;Implementation Notes&quot;">​</a></h2><p><strong>Completed by Orchestrator + 4 Dev Agents (2026-02-06)</strong></p><h3 id="changes-made" tabindex="-1">Changes Made: <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made:&quot;">​</a></h3><ol><li><p><strong>CommissionUzbekistan</strong> - Fixed from single <code>kgvpUzbekistan</code> field to correct 3 fields:</p><ul><li><code>kgvpMarketplaceUz</code> (FBS commission)</li><li><code>kgvpPaidStorageUz</code> (FBW commission)</li><li><code>kgvpSupplierUz</code> (DBS commission)</li></ul></li><li><p><strong>ModelsErrorModel</strong> - Added new type for acceptance/coefficients 400 error responses (5 fields)</p></li><li><p><strong>ModelsAcceptanceCoefficient</strong> - Added comprehensive type with 14 fields for warehouse acceptance coefficients</p></li><li><p><strong>Method signatures</strong> - Changed getTariffsBox, getTariffsPallet, getTariffsReturn to require <code>date: string</code> directly</p></li><li><p><strong>Type aliases</strong> - Added TariffItem, BoxTariffItem, PalletTariffItem, TariffsCommissionResponse</p></li></ol><h3 id="verification" tabindex="-1">Verification: <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification:&quot;">​</a></h3><ul><li>npx tsc --noEmit: 0 errors</li><li>Unit tests: 45/45 passed</li><li>TDD EPIC 39: 10/10 passed</li></ul>',57)])])}const f=t(i,[["render",o]]);export{m as __pageData,f as default};
